#include "../fm1/app/test_engine.c"
#include <assert.h>
int main(void){int32_t out[512];core_init();core_settings c={0};c.level=50;c.env=(pw_env_params){0,0,127,15};c.env2=(pw_env_params){10,20,60,30};c.voice_limit=c.unison_count=8;c.wave_quality=1;c.lfo=(pw_lfo_params){40,30,20,10};c.tracking.pitch_cutoff=20;c.filter=(pw_filter_params){1,60,40,80};c.chorus_mode=2;c.chorus_mix=50;c.delay_mode=1;c.delay_mix=40;c.delay_feedback=60;c.delay_time_ms=100;c.bloom_mode=1;c.bloom_length=16;c.bloom_mutation=70;c.arp_bpm=240;c.arp_gate_percent=50;core_set(&c);c.playing=1;core_set(&c);
for(unsigned j=0;j<1000;j++){c.voice_limit=j%2?4:8;c.position=j%101;c.unison_detune=j%101;c.filter.cutoff=j%128;core_set(&c);if(j%11==0)core_midi(0,0x90,48+j%24,100);if(j%13==0)core_midi(0,0x80,48+j%24,0);core_render(out,256,4096);assert(!core_worker_fault());}assert(core_worker_jobs()>1000);return 0;}
